// Generates the go build -overlay files for the two configurations:
//   overlay/tests.json  test programs (tests/go): gointypes/rt, fmt, errors,
//                       single-threaded sync, pure-Go math.
//   overlay/tsgo.json   the TypeScript 7 compiler harness: everything in
//                       tests plus the tsgo overlays (see overlay/README.md).
// Paths are absolute (GOROOT, the typescript-go checkout, the module cache),
// so the JSON files are machine-specific, git-ignored and regenerated by
// every script that needs them:  node overlay/gen.ts [--tsgo-dir DIR]
import { execFileSync } from "node:child_process";
import { existsSync, readdirSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const repo = resolve(here, "..");

function sh(cmd: string, args: string[], cwd?: string): string {
  return execFileSync(cmd, args, { cwd, encoding: "utf8" }).trim();
}

/** Every *.go file under dir, as paths relative to dir. */
function goFiles(dir: string): string[] {
  const out: string[] = [];
  const walk = (d: string) => {
    for (const name of readdirSync(d).sort()) {
      const p = join(d, name);
      if (statSync(p).isDirectory()) walk(p);
      else if (name.endsWith(".go")) out.push(relative(dir, p));
    }
  };
  if (existsSync(dir)) walk(dir);
  return out;
}

/**
 * Files of the original package replaced by the package's empty.go (a file
 * with only the package clause), because go/packages' in-memory overlays
 * cannot delete files.
 */
const emptied: Record<string, string[]> = {
  sync: ["poolqueue.go", "runtime2.go", "runtime2_lockrank.go"],
};

/** Overlay a tree of real Go files (overlay/<src>/<pkg>/...) onto root. */
function tree(replace: Record<string, string>, src: string, root: string) {
  const base = join(here, src);
  for (const f of goFiles(base)) {
    if (f.endsWith("/empty.go") || f === "empty.go") continue;
    replace[join(root, f)] = join(base, f);
  }
  for (const [pkg, files] of Object.entries(emptied)) {
    const empty = join(base, pkg, "empty.go");
    if (!existsSync(empty)) continue;
    for (const f of files) replace[join(root, pkg, f)] = empty;
  }
}

export function goroot(): string {
  return sh("go", ["env", "GOROOT"]);
}

/** The typescript-go module root (v7.0.2), from --tsgo-dir, $TSGO_DIR, the submodule, or the main worktree's submodule. */
export function tsgoDir(argv: string[] = process.argv): string {
  const i = argv.indexOf("--tsgo-dir");
  const candidates = [
    i >= 0 ? argv[i + 1] : undefined,
    process.env.TSGO_DIR,
    join(repo, "vendor/typescript/tsc"),
  ];
  try {
    const main = sh("git", ["worktree", "list", "--porcelain"], repo).split("\n")[0]!.slice(9);
    candidates.push(join(main, "vendor/typescript/tsc"));
  } catch {}
  for (const c of candidates) if (c && existsSync(join(c, "go.mod"))) return resolve(c);
  throw new Error("typescript-go checkout not found (pass --tsgo-dir or set TSGO_DIR)");
}

export function testsOverlay(): Record<string, string> {
  const replace: Record<string, string> = {};
  tree(replace, "std", join(goroot(), "src"));
  return replace;
}

export function tsgoOverlay(dir: string): Record<string, string> {
  const replace = testsOverlay();
  tree(replace, "tsgo", dir);
  const xxh3 = sh("go", ["list", "-m", "-f", "{{.Dir}}", "github.com/zeebo/xxh3"], dir);
  tree(replace, "xxh3", xxh3);
  // xxh3's own files that the replacement does not provide are emptied.
  const mine = new Set(goFiles(join(here, "xxh3")));
  const empty = join(here, "xxh3/empty.go");
  for (const f of readdirSync(xxh3).sort()) {
    if (f.endsWith(".go") && !f.endsWith("_test.go") && !mine.has(f))
      replace[join(xxh3, f)] = empty;
  }
  return replace;
}

function write(name: string, replace: Record<string, string>) {
  const sorted = Object.fromEntries(Object.entries(replace).sort(([a], [b]) => (a < b ? -1 : 1)));
  writeFileSync(join(here, name), JSON.stringify({ Replace: sorted }, null, 1) + "\n");
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  write("tests.json", testsOverlay());
  let dir: string | undefined;
  try {
    dir = tsgoDir();
  } catch (e) {
    console.error(String(e));
  }
  if (dir && existsSync(join(here, "tsgo"))) write("tsgo.json", tsgoOverlay(dir));
  console.log("wrote overlay/tests.json" + (dir ? " and overlay/tsgo.json" : ""));
}
